import { MCPServer } from '@mastra/mcp'
import { createTool } from '@mastra/core/tools'
import { z } from 'zod'

// 创建一份本地教学服务，公开查询、资源、提示模板和草稿操作。
export function makeService (owner = '公开通知') {
  const drafts = []
  const lookupNotice = createTool({
    id: 'lookup-notice', description: '查询教学活动通知，reading 为已知编号，FAIL 模拟查询失败。',
    inputSchema: z.object({ activityId: z.string().min(1) }),
    outputSchema: z.object({ status: z.enum(['已确认', '未查到', '查询失败']), venue: z.string().nullable(), source: z.string(), owner: z.string() }),
    execute: async ({ activityId }) => ({
      status: activityId === 'reading' ? '已确认' : activityId === 'FAIL' ? '查询失败' : '未查到',
      venue: activityId === 'reading' ? owner === '读者乙' ? '东门' : '南门' : null,
      source: '本地教学通知 v1', owner
    })
  })
  const saveDraft = createTool({
    id: 'save-draft', description: '在本服务进程内保存教学提醒草稿，不发送通知。',
    inputSchema: z.object({ text: z.string().min(1).max(200) }),
    outputSchema: z.object({ status: z.literal('草稿已保存'), count: z.number() }),
    execute: async ({ text }) => {
      drafts.push(text)
      return { status: '草稿已保存', count: drafts.length }
    }
  })
  const draftStatus = createTool({
    id: 'draft-status', description: '读取本服务已保存的教学草稿数量。',
    inputSchema: z.object({}), outputSchema: z.object({ count: z.number() }),
    execute: async () => ({ count: drafts.length })
  })
  const server = new MCPServer({
    id: 'activity-service', name: '活动通知教学服务', version: '1.0.0',
    tools: { lookupNotice, saveDraft, draftStatus },
    resources: {
      listResources: async () => [{ uri: 'activity://reading/notice', name: '阅读分享会通知', mimeType: 'text/plain' }],
      getResourceContent: async ({ uri }) => {
        if (uri !== 'activity://reading/notice') throw new Error('未找到教学资源')
        return { text: '阅读分享会周六下午两点开始，一点半开放入场，需要预约。未提供个人预约记录。' }
      }
    },
    prompts: {
      listPrompts: async () => [{ name: 'review-notice', description: '核对一份通知中的事实与缺口。', arguments: [{ name: 'material', description: '待核对的活动材料', required: true }] }],
      getPromptMessages: async ({ name, args }) => {
        if (name !== 'review-notice') throw new Error('未找到教学提示模板')
        return [{ role: 'user', content: { type: 'text', text: `请区分已确认信息和待确认事项，不补写个人预约状态。材料：${args.material}` } }]
      }
    }
  })
  return server
}

import { MCPClient } from '@mastra/mcp'
import { Mastra } from '@mastra/core'
import { LibSQLStore } from '@mastra/libsql'
import { makeService } from './service.js'
import { startLocalHttp } from './local-http.js'

// 把本项目的工具、资源和提示模板公开成一个 MCPServer。
const server = makeService()
// 真实 Mastra Server 项目可以注册该实例，交由服务路由承载。
const mastra = new Mastra({ mcpServers: { activity: server }, storage: new LibSQLStore({ id: 'published-tools', url: ':memory:' }) })
// 本例直接使用临时 HTTP 监听验证同一服务，不启动项目开发服务器。
const host = await startLocalHttp(() => server, [server])
// 模拟另一个 MCP 客户端，只使用公开的协议接口。
const external = new MCPClient({ id: 'external-reader', servers: { activity: { url: host.url } } })
try {
  const tools = await external.listTools()
  console.dir({ 已注册服务: Object.keys(mastra.listMCPServers()), 外部工具: Object.keys(tools), result: await tools.activity_lookupNotice.execute({ activityId: 'reading' }) }, { depth: 5 })
} finally {
  await external.disconnect()
  await host.close()
}

import assert from 'node:assert/strict'
import { randomUUID } from 'node:crypto'
import { createInterface } from 'node:readline/promises'
import { stdin, stdout } from 'node:process'
import { MCPClient } from '@mastra/mcp'
import { z } from 'zod'
import { makeService } from './service.js'
import { startLocalHttp } from './local-http.js'

// 串起请求归属、工具查询、资料读取和具体草稿确认，所有结果均来自本机教学服务。
async function main () {
  const reader = z.enum(['甲', '乙', '无效']).parse(process.argv[2] || '甲')
  const activityId = z.enum(['reading', 'unknown', 'FAIL']).parse(process.argv[3] || 'reading')
  const services = new Map([['demo-reader-a', makeService('读者甲')], ['demo-reader-b', makeService('读者乙')]])
  const host = await startLocalHttp(req => {
    const token = req.headers.authorization?.match(/^Bearer ([A-Za-z0-9-]+)$/)?.[1]
    return services.get(token)
  }, [...services.values()])
  const token = { 甲: 'demo-reader-a', 乙: 'demo-reader-b', 无效: 'demo-invalid' }[reader]
  const client = new MCPClient({
    id: `connected-case-${randomUUID()}`,
    servers: { activity: { url: host.url, requestInit: { headers: { Authorization: `Bearer ${token}` } } } }
  })
  try {
    const { tools, errors, errorDetails } = await client.listToolsWithErrors({ perServerTimeoutMs: 3000 })
    if (Object.keys(errors).length) {
      console.log('工具发现失败，HTTP 状态：', errorDetails.activity?.httpStatus)
      throw new Error('未取得本请求的工具，停止查询与保存。')
    }
    const notice = z.object({
      status: z.enum(['已确认', '未查到', '查询失败']),
      venue: z.string().nullable(), source: z.string(), owner: z.string()
    }).parse(await tools.activity_lookupNotice.execute({ activityId }))
    console.log('实际查询证据：')
    console.dir(notice)
    assert.equal(notice.owner, `读者${reader}`)
    if (notice.status !== '已确认') {
      assert.equal(notice.venue, null)
      console.log('没有可确认的通知，本次不生成或保存地点草稿。')
      console.log('服务草稿数量：', await tools.activity_draftStatus.execute({}))
      return
    }
    const resource = await client.resources.read('activity', 'activity://reading/notice')
    const prompt = await client.prompts.get({ serverName: 'activity', name: 'review-notice', args: { material: '个人预约结果未提供。' } })
    console.dir({ 已读取正文: resource, 模板消息: prompt }, { depth: 5 })
    const draft = `阅读分享会：从${notice.venue}入场（${notice.owner}范围）。来源：${notice.source}。出发前核对个人预约状态；本次只保存草稿，不发送通知。`
    console.log('待保存的完整草稿：\n', draft)
    const before = await tools.activity_draftStatus.execute({})
    assert.equal(before.count, 0)
    const terminal = createInterface({ input: stdin, output: stdout })
    let decision
    try {
      decision = await terminal.question('输入“确认”将此草稿保存到服务内存，其他输入拒绝：')
    } finally {
      terminal.close()
    }
    if (decision.trim() === '确认') {
      console.log('保存工具结果：', await tools.activity_saveDraft.execute({ text: draft }))
    }
    const after = await tools.activity_draftStatus.execute({})
    assert.equal(after.count, decision.trim() === '确认' ? 1 : 0)
    console.log('服务草稿数量：', after)
    console.log('本次核对完成；服务退出后内存草稿会清空。')
  } finally {
    try {
      await client.disconnect()
    } finally {
      await host.close()
    }
  }
}

// 让认证、协议和保存失败保留非零退出状态，便于区分未完成的任务。
main().catch(error => {
  console.error(error instanceof Error ? error.message : error)
  process.exitCode = 1
})

